const t=wb.getRange('AO9:AO1288');
log(wb.getRange('AO9').getCell(0,0));
t.setValues(f);
// independent check via raw values
const grid=wb.getRange('E9:AN1288').getValues();
const out=t.getValues();
const fmtBad=[];let mismatch=[],empty=[],zeroFirst=[],leadingZero=0,errs=0,neg=[];
grid.forEach((row,i)=>{const nums=row.filter(v=>v!==null&&v!==undefined&&v!=='');
 const e=row.find(v=>typeof v==='number'&&v!==0);
 const o=out[i][0];
 const nonNum=nums.filter(v=>typeof v!=='number'); if(nonNum.length) fmtBad.push([i+9,nonNum[0]]);
 if(typeof nums[0]==='number'&&nums[0]===0&&e!==undefined) leadingZero++;
 if(e===undefined){empty.push([i+9,nums.length,JSON.stringify(o)]);}
 else if(o!==e) mismatch.push([i+9,e,o]);
 if(typeof e==='number'&&e<0) neg.push([i+9,e]);
});
log({mismatch:mismatch.slice(0,10),nm:mismatch.length,empty:empty.slice(0,20),ne:empty.length,leadingZero,neg,fmtBad:fmtBad.slice(0,5)});
